		return endSlayerXp;
	}

	public void setEndSlayerXp(int endSlayerXp)
	{
		this.endSlayerXp = endSlayerXp;
	}

	public int getSlayerXpGained()
	{
		return Math.max(0, endSlayerXp - startSlayerXp);
