		this.gson = gson.newBuilder().setPrettyPrinting().create();
		this.historyDirectory = historyDirectory;
		historyFile = historyDirectory.resolve(FILE_NAME);
	}

	public SlayerHistory load() throws IOException
	{
		if (!Files.exists(historyFile))
		{
			return new SlayerHistory();
		}

		try (Reader reader = Files.newBufferedReader(historyFile, StandardCharsets.UTF_8))
		{
			SlayerHistory history = gson.fromJson(reader, SlayerHistory.class);
			if (history == null)
			{
				history = new SlayerHistory();
			}
			history.normalize();
			return history;
		}
	}

	public void save(SlayerHistory history) throws IOException
	{
		Files.createDirectories(historyDirectory);
		Path temporaryFile = historyDirectory.resolve(FILE_NAME + ".new");
		try (Writer writer = Files.newBufferedWriter(temporaryFile, StandardCharsets.UTF_8))
		{
			gson.toJson(history, writer);
		}

		try
		{
			Files.move(temporaryFile, historyFile, StandardCopyOption.REPLACE_EXISTING,
				StandardCopyOption.ATOMIC_MOVE);
		}
		catch (AtomicMoveNotSupportedException ex)
		{
			Files.move(temporaryFile, historyFile, StandardCopyOption.REPLACE_EXISTING);
		}
	}
}

package com.ruffensteint.mortimerslayertracker.service;

import com.ruffensteint.mortimerslayertracker.model.SlayerAssignment;
import java.util.List;
import java.util.Optional;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.Skill;
import net.runelite.api.gameval.DBTableID;
import net.runelite.api.gameval.VarPlayerID;
import net.runelite.api.gameval.VarbitID;

public class SlayerAssignmentReader
{
	private final Client client;

	@Inject
	public SlayerAssignmentReader(Client client)
	{
		this.client = client;
	}

	public Optional<SlayerAssignment> readMortimerAssignment()
	{
		int amount = client.getVarpValue(VarPlayerID.SLAYER_COUNT);
		int modifierId = client.getVarbitValue(VarbitID.SLAYER_MODIFIER_ID);
		int slayerXp = client.getSkillExperience(Skill.SLAYER);
		if (amount <= 0 || modifierId <= 0 || slayerXp <= 0)
		{
			return Optional.empty();
		}

		Optional<String> taskName = readTaskName();
		if (!taskName.isPresent())
		{
			return Optional.empty();
		}

		int assignedAmount = client.getVarpValue(VarPlayerID.SLAYER_COUNT_ORIGINAL);
		String modifier = readModifierName(modifierId).orElse("Modifier " + modifierId);
		int modifierValue = client.getVarbitValue(VarbitID.SLAYER_MODIFIER_VALUE);
		boolean negative = client.getVarbitValue(VarbitID.SLAYER_MODIFIER_NEGATIVE) == 1;
		if (modifierValue > 0)
		{
			modifier += " (" + (negative ? "-" : "+") + modifierValue + ")";
		}

		return Optional.of(new SlayerAssignment(
			taskName.get(),
			assignedAmount > 0 ? assignedAmount : amount,
			modifier,
			modifierValue,
			negative,
			slayerXp));
	}

	private Optional<String> readTaskName()
	{
		int taskId = client.getVarpValue(VarPlayerID.SLAYER_TARGET);
		List<Integer> taskRows = client.getDBRowsByValue(
			DBTableID.SlayerTask.ID,
			DBTableID.SlayerTask.COL_ID,
			0,
			taskId);
		if (taskRows.isEmpty())
		{
			return Optional.empty();
		}

		int taskRow = taskRows.get(0);
		if (taskRow == DBTableID.SlayerTask.Row.SLAYER_TARGET_BOSS)
		{
			List<Integer> bossRows = client.getDBRowsByValue(
				DBTableID.SlayerTaskSublist.ID,
				DBTableID.SlayerTaskSublist.COL_TASK_SUBTABLE_ID,
				0,
				client.getVarbitValue(VarbitID.SLAYER_TARGET_BOSSID));
			if (bossRows.isEmpty())
			{
				return Optional.empty();
			}
			taskRow = (Integer) client.getDBTableField(
				bossRows.get(0), DBTableID.SlayerTaskSublist.COL_TASK, 0)[0];
		}

		return Optional.of((String) client.getDBTableField(
			taskRow, DBTableID.SlayerTask.COL_NAME_UPPERCASE, 0)[0]);
	}

	private Optional<String> readModifierName(int modifierId)
	{
		List<Integer> modifierRows = client.getDBRowsByValue(
			DBTableID.SlayerModifiers.ID,
			DBTableID.SlayerModifiers.COL_ID,
			0,
			modifierId);
		if (modifierRows.isEmpty())
		{
			return Optional.empty();
		}

		return Optional.of((String) client.getDBTableField(
			modifierRows.get(0), DBTableID.SlayerModifiers.COL_NAME, 0)[0]);
	}
}

package com.ruffensteint.mortimerslayertracker.service;

import com.ruffensteint.mortimerslayertracker.model.SlayerAssignment;
import com.ruffensteint.mortimerslayertracker.model.SlayerHistory;
import com.ruffensteint.mortimerslayertracker.model.SlayerTaskRecord;
import java.util.Objects;

public class TaskTracker
{
	private boolean assignmentVisible;

	public boolean startAssignment(SlayerHistory history, SlayerAssignment assignment)
	{
		SlayerTaskRecord activeTask = history.getActiveTask();
		if (matches(activeTask, assignment))
		{
			activeTask.setModifierValue(assignment.getModifierValue());
			activeTask.setModifierNegative(assignment.isModifierNegative());
			assignmentVisible = true;
			return false;
		}
		if (assignmentVisible && matches(latestTask(history), assignment))
		{
			return false;
		}

		if (activeTask != null)
		{
			complete(activeTask, assignment.getSlayerXp());
		}

		SlayerTaskRecord task = new SlayerTaskRecord();
		task.setTaskNumber(history.getMortimerTaskCount() + 1);
		task.setMonster(assignment.getMonster());
		task.setAssignedAmount(assignment.getAssignedAmount());
		task.setModifier(assignment.getModifier());
		task.setModifierValue(assignment.getModifierValue());
		task.setModifierNegative(assignment.isModifierNegative());
		task.setStartSlayerXp(assignment.getSlayerXp());
		history.addTask(task);
		assignmentVisible = true;
		return true;
	}

	public void clearAssignment()
	{
		assignmentVisible = false;
	}

	public boolean recordCompletedTaskCount(SlayerHistory history, int completedTaskCount, int endSlayerXp)
	{
		if (completedTaskCount <= history.getMortimerTaskCount())
		{
			return false;
		}

		history.setMortimerTaskCount(completedTaskCount);
		SlayerTaskRecord activeTask = history.getActiveTask();
		if (activeTask == null)
		{
			return false;
		}

		complete(activeTask, endSlayerXp);
		return true;
	}

	public boolean recordSuperiorSpawn(SlayerHistory history)
	{
		SlayerTaskRecord activeTask = history.getActiveTask();
		if (activeTask == null)
		{
			return false;
		}
		activeTask.incrementSuperiorCount();
		return true;
	}

	public boolean recordClueDrop(SlayerHistory history, int quantity)
	{
		SlayerTaskRecord activeTask = history.getActiveTask();
		if (activeTask == null || !activeTask.isClueModifier() || quantity <= 0)
		{
			return false;
		}
		activeTask.addClueDrops(quantity);
		return true;
	}

	public boolean recordSuperiorLoot(SlayerHistory history, int itemId, String name, int quantity)
	{
		SlayerTaskRecord activeTask = history.getActiveTask();
		if (activeTask == null || quantity <= 0)
		{
			return false;
		}
		activeTask.addSuperiorLoot(itemId, name, quantity);
		return true;
	}

	public boolean updateSlayerXp(SlayerHistory history, int currentSlayerXp)
	{
		SlayerTaskRecord activeTask = history.getActiveTask();
		if (activeTask == null || currentSlayerXp < activeTask.getStartSlayerXp())
		{
			return false;
		}

		int totalXp = currentSlayerXp - activeTask.getStartSlayerXp();
		int baseXp = totalXp;
		int bonusXp = 0;
		if (activeTask.isSlayerXpModifier()
			&& !activeTask.isModifierNegative()
			&& activeTask.getModifierValue() > 0)
		{
			baseXp = Math.round(totalXp * 100.0f / (100 + activeTask.getModifierValue()));
			bonusXp = totalXp - baseXp;
		}
		activeTask.setSlayerXpBreakdown(baseXp, bonusXp);
		return true;
	}

	private static boolean matches(SlayerTaskRecord activeTask, SlayerAssignment assignment)
	{
		return activeTask != null
			&& Objects.equals(activeTask.getMonster(), assignment.getMonster())
			&& activeTask.getAssignedAmount() == assignment.getAssignedAmount()
			&& Objects.equals(activeTask.getModifier(), assignment.getModifier());
	}

	private static SlayerTaskRecord latestTask(SlayerHistory history)
	{
		if (history.getTasks().isEmpty())
		{
			return null;
		}
		return history.getTasks().get(history.getTasks().size() - 1);
	}

	private static void complete(SlayerTaskRecord task, int endSlayerXp)
	{
		task.setEndSlayerXp(endSlayerXp);
		task.setCompleted(true);
	}
}

